<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class long_tail_keywords extends lib { var $log_id = 'pseudo-original'; public function init() { add_action( 'add_meta_boxes', array($this, 'add_meta_boxes') ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-long-tail-keywords', array($this, 'get_long_tail_keywords') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-long-tail-keywords', array($this, 'get_long_tail_keywords') ); } public function add_meta_boxes() { $id = 'long_tail_keywords'; $title = __( 'Long Tail Keywords', $this->text_domain ); $callback = array($this, 'long_tail_keywords'); $screen = get_post_types(array('public'=>true, 'show_ui' => true)); $context = 'side'; $priority = 'default'; $callback_args = null; add_meta_box($id, $title, $callback, $screen, $context, $priority, $callback_args); } public function long_tail_keywords($post) { ?><div class="tagsdiv">
	<p><select class="selectstyle" id="long_tail_keywords_types" style="width: 100%;">
		<optgroup label="<?php _ex('Commercial', 'version', $this->text_domain); ?>">
			<option value="5118" <?php selected($this->options->qc_pseudo_original_long_tail_keywords_api=='5118', 1); ?>><?php _e('5118 Big Data - Long Tail Keyword Mining API (wyc.5118.com)', $this->text_domain); ?></option>
		</optgroup>
		<optgroup label="<?php _e('Free', $this->text_domain); ?>">
			<option value="toutiao" <?php selected($this->options->qc_pseudo_original_long_tail_keywords_api=='toutiao', 1); ?>><?php _e('Toutiao', $this->text_domain); _e(' (Recommened)', $this->text_domain); ?></option>
		</optgroup>
	</select></p>
	<p class="ajaxtag hide-if-no-js">
		<input id="long_tail_keywords_input" type="text" class="newtag form-input-tip ui-autocomplete-input" size="16" value="" placeholder="<?php _e('Leave blank to get the title automatically', $this->text_domain); ?>" />
		<input id="long_tail_keywords_submit" type="button" class="button tagadd" value="<?php _e('Suggest', $this->text_domain); ?>" />
	</p>
	<p id="long_tail_keywords_results"></p>
	<p class="qc-icon info"><?php printf(__('If the content cannot be obtained, you may need to <a href="%s" target="_blank">update settings of the corresponding API</a>.', $this->text_domain), admin_url('admin.php?page=pseudo-original-settings#long-tail-keywords')); ?></p>
	<input type="text" id="long_tail_keywords_clipboard" style="position: fixed; left: -5000px; top: -5000px;" value="">
</div><?php
 } public function get_long_tail_keywords() { extract($_POST); $keywords = array(); switch ($type) { case '5118': $host = "http://apis.5118.com"; $path = "/keyword/word"; $method = "POST"; $apikey = $this->options->qc_pseudo_original_long_tail_keywords_5118_apikey; $headers = array(); array_push($headers, "Authorization:" . $apikey); array_push($headers, "Content-Type".":"."application/x-www-form-urlencoded; charset=UTF-8"); $querys = ""; $bodys = "keyword={$input}&page_index=1"; $url = $host . $path; $curl = curl_init(); curl_setopt($curl, CURLOPT_CUSTOMREQUEST, $method); curl_setopt($curl, CURLOPT_URL, $url); curl_setopt($curl, CURLOPT_HTTPHEADER, $headers); curl_setopt($curl, CURLOPT_FAILONERROR, false); curl_setopt($curl, CURLOPT_RETURNTRANSFER, true); curl_setopt($curl, CURLOPT_HEADER, false); if (1 == strpos("$".$host, "https://")) { curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, false); } curl_setopt($curl, CURLOPT_POSTFIELDS, $bodys); $results = curl_exec($curl); curl_close($curl); $arr = json_decode($results, true); if ($arr && $arr['errcode'] == 0) { foreach ($arr['data']['word'] as $word) { $keywords[] = $word['keyword']; } } else { do_action( 'qqworld-collector-log', $this->log_id, 'Long Tail Keywords 5118 error, $results', print_r($results, true) ); } break; case 'toutiao': $url = 'https://mp.toutiao.com/mp/agw/creator_helper/freestyle/get_ai_title'; $args = array( 'method' => 'post', 'headers' => 'User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/92.0.4515.131 Safari/537.36;
' . $this->options->qc_pseudo_original_long_tail_keywords_toutiao_cookies, 'content' => '{"title":"'.$input.'","content":"","extra":""}' ); $result = apply_filters( 'qqworld-collector-download-from-url', $url, $args ); $json = json_decode($result['file'], true); if ($json && count($json['ai_titles'])) { foreach ($json['ai_titles'] as $title) { $keywords[] = $title['title']; } } break; } if ($keywords) { $results = array( 'success' => 1, 'keywords' => $keywords ); } else { $results = array( 'success' => 0, 'msg' => __('No Long Tail Keywords found, please check the settings.', $this->text_domain) ); } print json_encode($results); exit; } } ?>